function Dot({flow,paused,index,map}:{flow:Flow;paused:boolean;index:number;map:Map<string,Area>}){const ref=useRef<THREE.Mesh>(null),t=useRef(index*.31%1),a=map.get(flow.from),b=map.get(flow.to);const curve=useMemo(()=>a&&b?new THREE.QuadraticBezierCurve3(new THREE.Vector3(a.position[0],.85,a.position[2]),new THREE.Vector3((a.position[0]+b.position[0])/2,1.7,(a.position[2]+b.position[2])/2),new THREE.Vector3(b.position[0],.85,b.position[2])):null,[a,b]);useFrame((_,d)=>{if(paused||!ref.current||!curve)return;t.current=(t.current+d*(.08+flow.volume/500))%1;ref.current.position.copy(curve.getPoint(t.current))});return curve?<mesh ref={ref}><sphereGeometry args={[.11,14,14]}/><meshStandardMaterial color={FLOW[flow.kind]} emissive={FLOW[flow.kind]} emissiveIntensity={.8}/></mesh>:null}
function Scene({areas,flows,selected,onSelect,kinds,paused}:{areas:Area[];flows:Flow[];selected:string;onSelect:(id:string)=>void;kinds:Kind[];paused:boolean}){const map=useMemo(()=>new Map(areas.map(a=>[a.id,a])),[areas]);return <><color attach="background" args={["#09090b"]}/><fog attach="fog" args={["#09090b",16,34]}/><ambientLight intensity={.9}/><directionalLight position={[7,12,8]} intensity={1.6}/><gridHelper args={[24,24,"#27272a","#18181b"]}/>{areas.map(a=><group key={a.id} position={[a.position[0],a.size[1]/2,a.position[2]]}><RoundedBox args={a.size} radius={.15} smoothness={4} onClick={e=>{e.stopPropagation();onSelect(a.id)}}><meshStandardMaterial color={STATUS[a.status]} emissive={STATUS[a.status]} emissiveIntensity={selected===a.id?0.35:0.08}/></RoundedBox><Html position={[0,1,0]} center distanceFactor={12}><button type="button" onClick={()=>onSelect(a.id)} className="rounded border border-white/10 bg-zinc-950/90 px-2 py-1 text-[10px] font-semibold text-white">{a.name}</button></Html></group>)}{flows.filter(f=>kinds.includes(f.kind)).map(f=>{const a=map.get(f.from),b=map.get(f.to);return !a||!b?null:<React.Fragment key={f.id}><Line points={[[a.position[0],.85,a.position[2]],[b.position[0],.85,b.position[2]]]} color={FLOW[f.kind]} transparent opacity={.22} lineWidth={1}/>{Array.from({length:Math.max(1,Math.min(3,Math.ceil(f.volume/10)))},(_,i)=><Dot key={i} flow={f} paused={paused} index={i} map={map}/>)}</React.Fragment>})}<OrbitControls makeDefault enableDamping minDistance={9} maxDistance={25} maxPolarAngle={Math.PI/2.05}/></>}
export default function App(){const[snapshot,setSnapshot]=useState<Snapshot|null>(null),[events,setEvents]=useState<TwinEvent[]>([]),[selected,setSelected]=useState(""),[kinds,setKinds]=useState<Kind[]>(["supply","medication"]),[paused,setPaused]=useState(false),[loading,setLoading]=useState(true),[refreshing,setRefreshing]=useState(false),[error,setError]=useState<string|null>(null);const since=useRef<string|null>(null);const load=useCallback(async(initial=false)=>{initial?setLoading(true):setRefreshing(true);try{const suffix=since.current?`&since=${encodeURIComponent(since.current)}`:"";const[s,e]=await Promise.all([fetch("/api/twin/hospital",{cache:"no-store"}),fetch(`/api/twin/events?limit=12${suffix}`,{cache:"no-store"})]);if(!s.ok||!e.ok)throw new Error(`Twin API HTTP ${!s.ok?s.status:e.status}`);const next=await s.json()as Snapshot,batch=await e.json()as EventBatch;setSnapshot(next);setEvents(old=>{const u=new Map([...batch.events,...old].map(x=>[x.id,x]));return[...u.values()].sort((a,b)=>Date.parse(b.occurredAt)-Date.parse(a.occurredAt)).slice(0,12)});since.current=batch.generatedAt;setSelected(old=>old&&next.areas.some(a=>a.id===old)?old:next.areas.find(a=>a.status==="critical")?.id??next.areas[0]?.id??"");setError(null)}catch(x){setError(x instanceof Error?x.message:"No fue posible actualizar el gemelo digital.")}finally{setLoading(false);setRefreshing(false)}},[]);useEffect(()=>{void load(true);const id=window.setInterval(()=>void load(),5000);return()=>clearInterval(id)},[load]);const current=useMemo(()=>snapshot?.areas.find(a=>a.id===selected)??null,[snapshot,selected]);const toggle=(k:Kind)=>setKinds(v=>v.includes(k)?v.length===1?v:v.filter(x=>x!==k):[...v,k]);if(loading&&!snapshot)return <State icon={<RefreshCw className="h-4 w-4 animate-spin"/>} text="Cargando gemelo digital…"/>;if(!snapshot)return <State icon={<WifiOff className="h-4 w-4 text-amber-400"/>} text={error??"Gemelo digital no disponible"} retry={()=>void load(true)}/>;return <div className="flex h-full w-full flex-col overflow-hidden bg-zinc-950 text-zinc-100"><header className="flex flex-wrap items-center justify-between gap-2 border-b border-zinc-800 px-3 py-2"><div><div className="flex items-center gap-2 text-sm font-semibold"><Activity className="h-4 w-4 text-cyan-400"/>Hospital Digital Twin · Abastecimiento<span className="inline-flex items-center gap-1 text-[9px] font-normal text-zinc-500"><Wifi className="h-3 w-3"/>{snapshot.source==="remote"?"FUENTE REAL":"DEMO"}</span></div><div className="text-[10px] text-zinc-500">TwinDataSource · snapshot + eventos · actualización 5 s</div></div><div className="flex flex-wrap gap-1">{(["supply","medication","patient","data"]as Kind[]).map(k=><button type="button" key={k} onClick={()=>toggle(k)} className={`rounded border px-2 py-1 text-[10px] ${kinds.includes(k)?"border-zinc-500 bg-zinc-700":"border-zinc-800 bg-zinc-900 text-zinc-500"}`}>{LABEL[k]}</button>)}<IconButton onClick={()=>setPaused(v=>!v)}>{paused?<Play className="h-3.5 w-3.5"/>:<Pause className="h-3.5 w-3.5"/>}</IconButton><IconButton onClick={()=>void load()}><RefreshCw className={`h-3.5 w-3.5 ${refreshing?"animate-spin":""}`}/></IconButton></div></header>{error&&<div className="flex items-center gap-2 border-b border-amber-900/30 bg-amber-950/20 px-3 py-1.5 text-[10px] text-amber-300"><AlertTriangle className="h-3 w-3"/>{error}. Se conserva el último estado válido.</div>}<div className="grid min-h-0 flex-1 grid-cols-[minmax(0,1fr)_240px] max-[760px]:grid-cols-1"><div className="min-h-[260px]"><Canvas camera={{position:[13,11,14],fov:48}} dpr={[1,1.5]}><Scene areas={snapshot.areas} flows={snapshot.flows} selected={selected} onSelect={setSelected} kinds={kinds} paused={paused}/></Canvas></div><aside className="overflow-auto border-l border-zinc-800 p-3 max-[760px]:border-l-0 max-[760px]:border-t">{current&&<><div className="text-[9px] uppercase tracking-[.16em] text-zinc-500">Área seleccionada</div><div className="mt-1 text-lg font-semibold">{current.name}</div><div className="mt-3 grid grid-cols-2 gap-2"><Metric label="Stock sano" value={metric(current.metrics.stockHealth,"%")}/><Metric label="Actividad" value={metric(current.metrics.activity)}/><Metric label="Ocupación" value={metric(current.metrics.occupancy,"%")}/><Metric label="Pendientes" value={metric(current.metrics.pending)}/></div><div className="mt-3 rounded border border-zinc-800 bg-zinc-900/60 p-2.5 text-[10px] text-zinc-400">Estado: <strong style={{color:STATUS[current.status]}}>{current.status==="critical"?"CRÍTICO":current.status==="attention"?"ATENCIÓN":"NORMAL"}</strong><br/>Fuente: {snapshot.source==="remote"?"integración externa solo lectura":"proveedor demo de Fase 2"}.</div></>}<div className="mt-4 border-t border-zinc-800 pt-3"><div className="mb-2 text-[9px] uppercase tracking-[.16em] text-zinc-500">Eventos recientes</div><div className="space-y-1.5">{events.slice(0,5).map(e=><div key={e.id} className="rounded border border-zinc-800 bg-zinc-900/50 p-2"><div className="flex items-center justify-between gap-2"><span className="truncate text-[10px] text-zinc-300">{eventLabel(e)}</span><span className="h-1.5 w-1.5 shrink-0 rounded-full" style={{background:STATUS[e.severity]}}/></div><div className="mt-0.5 text-[9px] text-zinc-600">{new Date(e.occurredAt).toLocaleTimeString()}</div></div>)}{!events.length&&<div className="text-[10px] text-zinc-600">Sin eventos nuevos.</div>}</div></div></aside></div></div>}
function metric(v:number|undefined,s=""){return typeof v==="number"?`${Math.round(v)}${s}`:"—"}function eventLabel(e:TwinEvent){if(e.type==="inventory.low")return`Inventario bajo · ${e.areaId??"área"}`;if(e.type==="medication.moved")return`Medicamento · ${e.from??"?"} → ${e.to??"?"}`;if(e.type==="supply.moved")return`Abastecimiento · ${e.from??"?"} → ${e.to??"?"}`;if(e.type==="patient.moved")return`Paciente · ${e.from??"?"} → ${e.to??"?"}`;if(e.type==="operating_room.delayed")return`Retraso · ${e.areaId??"quirófano"}`;return e.type}function Metric({label,value}:{label:string;value:string}){return <div className="rounded border border-zinc-800 bg-zinc-900/70 p-2"><div className="text-[9px] uppercase text-zinc-500">{label}</div><div className="mt-1 text-lg font-semibold tabular-nums">{value}</div></div>}function IconButton({onClick,children}:{onClick:()=>void;children:React.ReactNode}){return <button type="button" onClick={onClick} className="grid h-7 w-7 place-items-center rounded border border-zinc-700 bg-zinc-900">{children}</button>}function State({icon,text,retry}:{icon:React.ReactNode;text:string;retry?:()=>void}){return <div className="grid h-full w-full place-items-center bg-zinc-950 p-6 text-zinc-300"><div className="max-w-sm rounded border border-zinc-800 bg-zinc-900 p-4 text-xs"><div className="flex items-center gap-2">{icon}{text}</div>{retry&&<button type="button" onClick={retry} className="mt-3 rounded border border-zinc-700 px-3 py-1.5 hover:bg-zinc-800">Reintentar</button>}</div></div>}
